import type { AiAgentVersionState } from './constants';
/**
 * Type representing the version details configuration for an AI Agent.
 */
export type AiAgentVersionDetailsType = {
    /** Condition string for this version */
    condition?: string;
    /** Instructions that guide the agent's behavior for this version */
    instructions?: string;
    /** State of the version */
    state?: AiAgentVersionState;
    /** Version name */
    name?: string;
    /** Version number */
    number?: number;
};
